interface MembershipPlan {String getName();int getMonths();double calculateFee();}
class MonthlyPlan implements MembershipPlan {public String getName(){return "Monthly";}public int getMonths(){return 1;}public double calculateFee(){return 1000;}}
class QuarterlyPlan implements MembershipPlan {public String getName(){return "Quarterly";}public int getMonths(){return 3;}public double calculateFee(){return 2700;}}
class AnnualPlan implements MembershipPlan {public String getName(){return "Annual";}public int getMonths(){return 12;}public double calculateFee(){return 9000;}}
class Member {final String name;Member(String n){name=n;}}
class Membership {enum Status{ACTIVE,FROZEN,EXPIRED}final Member member;final MembershipPlan plan;final double fee;Status status=Status.ACTIVE;Membership(Member m,MembershipPlan p){member=m;plan=p;fee=p.calculateFee();}boolean checkIn(){return status==Status.ACTIVE;}void freeze(){if(status==Status.EXPIRED)throw new IllegalStateException("Cannot freeze an Expired membership.");if(status!=Status.ACTIVE)throw new IllegalStateException();status=Status.FROZEN;}void unfreeze(){if(status!=Status.FROZEN)throw new IllegalStateException();status=Status.ACTIVE;}void expire(){status=Status.EXPIRED;}}
public class Main {public static void main(String[]args){Member asha=new Member("Asha"),ravi=new Member("Ravi");Membership a=new Membership(asha,new QuarterlyPlan()),r=new Membership(ravi,new MonthlyPlan());System.out.printf("Quarterly membership created for Asha. Fee: ₹%.2f. Status: Active.%n",a.fee);System.out.printf("Monthly membership created for Ravi. Fee: ₹%.2f. Status: Active.%n",r.fee);System.out.println(a.checkIn()?"Asha checked in successfully.":"Check-in denied.");a.freeze();System.out.println("Asha's membership frozen. Status: Frozen.");System.out.println(a.checkIn()?"Asha checked in successfully.":"Check-in denied: Asha's membership is Frozen.");r.expire();System.out.println("Ravi's membership expired. Status: Expired.");try{r.freeze();}catch(IllegalStateException e){System.out.println(e.getMessage());}}}